    // TC-005 - Standard-length mobile number reveals only the last 4 digits
    @Test
    public void standardLengthMobileNumberRevealsOnlyLastFourDigits() {
        String requestBody = """
            {
              "storeName": "ABC Store - Dhaka Branch",
              "storeLocation": "123 - Store address",
              "notificationMobileNumber": "01712345678"
            }
            """;
        given().contentType(ContentType.JSON).header("X-Auth-Subject", "12345").body(requestBody).when().post("/api/v1/onboarding").then().statusCode(anyOf(is(200), is(201)));
    }

    // TC-006 - Null mobile number passed to the masker does not throw
