    // TC-012
    @Test
    public void submitKycInformationSuccessfully() {
        long timestamp = System.currentTimeMillis();
        String requestBody = """
            {
              "storeName": "Store_%d",
              "storeLocation": "123 Main Street, Dhaka",
              "notificationMobileNumber": "01670636253"
            }
            """.formatted(timestamp);
        given().contentType(ContentType.JSON).header("X-Auth-Subject", "12345").header("auth-subject", "12345").body(requestBody).when().post("/api/v1/onboarding").then().statusCode(anyOf(is(200), is(201))).body("success", equalTo(true)).body("data.kycStatus", notNullValue());
    }

    // TC-015
    @Test
    public void whenKycRegistrationFailsDuringMerchantOnboardingProcessHandlesFailure() {
        String requestBody = """
            {
              "storeName": "Test Store %d",
              "storeLocation": "Dhaka",
              "notificationMobileNumber": "9999999999"
            }
            """.formatted(System.currentTimeMillis());
        Response response = given().header("X-Auth-Subject", "12345").contentType(ContentType.JSON).body(requestBody).when().post("/api/v1/onboarding");
        int statusCode = response.getStatusCode();
        if (statusCode >= 200 && statusCode < 300) {
            response.then().body("data.kycStatus", anyOf(equalTo("REJECTED"), equalTo("INCOMPLETE"), equalTo("FAILED")));
        } else {
            Assert.assertTrue(statusCode >= 400 && statusCode < 500, "Expected 2xx with failed KYC status or 4xx status. Got status: " + statusCode);
        }
    }

